insert='''const tournamentShareMaintenanceReplay=url.pathname.match(/^\\/api\\/tournaments\\/([^/]+)\\/share\\/health\\/maintenance\\/replay$/); if(tournamentShareMaintenanceReplay && request.method==='POST'){if(!env.DB)return json({error:'D1 yapılandırılmamış.'},{status:503});const user=await authUser(request,env);if(!user)return json({error:'Giriş gerekli.'},{status:401});try{const id=decodeURIComponent(tournamentShareMaintenanceReplay[1]);const t=await env.DB.prepare(`SELECT id,created_by FROM tournaments WHERE id=?`).bind(id).first<any>();if(!t)return json({error:'Turnuva bulunamadı.'},{status:404});if(t.created_by!==user.id)return json({error:'Sadece turnuva sahibi replay çalıştırabilir.'},{status:403});const now=new Date();const cutoffs={audit:new Date(now.getTime()-90*86400000).toISOString(),cache:new Date(now.getTime()-90*86400000).toISOString().slice(0,10),alerts:new Date(now.getTime()-180*86400000).toISOString(),runs:new Date(now.getTime()-90*86400000).toISOString()};const q=async(sql:string,...args:any[])=>Number((await env.DB.prepare(sql).bind(...args).first<any>())?.n||0);const plan={auditAggregateCandidates:await q(`SELECT COUNT(*) n FROM tournament_share_audit WHERE tournament_id=? AND created_at>=?`,id,new Date(now.getTime()-91*86400000).toISOString()),auditRetentionCandidates:await q(`SELECT COUNT(*) n FROM tournament_share_audit WHERE tournament_id=? AND created_at<?`,id,cutoffs.audit),cacheRetentionCandidates:await q(`SELECT COUNT(*) n FROM tournament_share_cache_daily WHERE tournament_id=? AND day<?`,id,cutoffs.cache),alertRetentionCandidates:await q(`SELECT COUNT(*) n FROM tournament_share_alert_history WHERE tournament_id=? AND last_seen_at<?`,id,cutoffs.alerts),maintenanceRetentionCandidates:await q(`SELECT COUNT(*) n FROM tournament_share_maintenance_runs WHERE ran_at<?`,cutoffs.runs)};const replayId=crypto.randomUUID();const payload={version:'v63',mode:'dry-run',generatedAt:now.toISOString(),cutoffs,plan};await env.DB.prepare(`INSERT INTO tournament_share_maintenance_replays(id,tournament_id,created_at,status,payload) VALUES(?,?,?,?,?)`).bind(replayId,id,now.toISOString(),'dry-run',JSON.stringify(payload)).run();return json({ok:true,replayId,...payload});}catch{return json({error:'Bakım replay simülasyonu alınamadı.'},{status:400});}}\nconst tournamentShareAlertAudit=url.pathname.match(/^\\/api\\/tournaments\\/([^/]+)\\/share\\/health\\/alerts\\/audit$/); if(tournamentShareAlertAudit && request.method==='GET'){if(!env.DB)return json({error:'D1 yapılandırılmamış.'},{status:503});const user=await authUser(request,env);if(!user)return json({error:'Giriş gerekli.'},{status:401});try{const id=decodeURIComponent(tournamentShareAlertAudit[1]);const t=await env.DB.prepare(`SELECT id,created_by FROM tournaments WHERE id=?`).bind(id).first<any>();if(!t)return json({error:'Turnuva bulunamadı.'},{status:404});if(t.created_by!==user.id)return json({error:'Sadece turnuva sahibi erişebilir.'},{status:403});const u=new URL(request.url);const alert=u.searchParams.get('alert')||'';const action=u.searchParams.get('action')||'';const limit=Math.max(1,Math.min(100,Number(u.searchParams.get('limit')||50)));let sql=`SELECT aa.alert,aa.action,aa.occurrences,aa.created_at createdAt FROM tournament_share_alert_ack_audit aa JOIN tournament_share_alert_history h ON h.share_id=aa.share_id AND h.alert=aa.alert WHERE h.tournament_id=?`;const args:any[]=[id];if(alert){sql+=' AND aa.alert=?';args.push(alert.slice(0,64));}if(action){sql+=' AND aa.action=?';args.push(action.slice(0,32));}sql+=` ORDER BY aa.created_at DESC LIMIT ${limit}`;const rows=(await env.DB.prepare(sql).bind(...args).all<any>()).results||[];return json({version:'v63',filters:{alert:alert||null,action:action||null,limit},rows});}catch{return json({error:'Alert audit alınamadı.'},{status:400});}}\n'''
